-- وارد کردن کالاهای شاتوت به حساب‌یار
-- پیش‌نیاز: ابتدا یک‌بار در اپ ثبت‌نام کنید تا سازمان ساخته شود.
-- این اسکریپت org_id و branch_id شما را خودکار پیدا می‌کند.

do $$
declare
  v_org uuid;
  v_branch uuid;
  v_uid uuid;
  v_prod uuid;
  v_var uuid;
begin
  select org_id, branch_id, user_id into v_org, v_branch, v_uid
    from public.memberships where role='owner' and is_active order by created_at limit 1;

end$$;
